      font: inherit;
      text-align: right;
      text-decoration: none;
      cursor: pointer;
    }

    button.row:focus-visible,
    a.row:focus-visible,
    .switch input:focus-visible + .slider {
      outline: 3px solid rgba(0, 109, 91, 0.2);
      outline-offset: 2px;
    }

    .icon {
      flex: 0 0 42px;
      width: 42px;
      height: 42px;
      display: grid;
      place-items: center;
      border-radius: 13px;
      color: var(--primary);
      background: var(--primary-soft);
    }

    .icon svg {
      width: 21px;
      height: 21px;
      fill: none;
      stroke: currentColor;
      stroke-width: 1.8;
      stroke-linecap: round;
      stroke-linejoin: round;
    }

    .row-content {
      min-width: 0;
