    .row-value {
      margin: 0;
      color: var(--muted);
      font-size: 12px;
      line-height: 1.45;
      direction: rtl;
    }

    .chevron {
      flex: 0 0 auto;
      width: 19px;
      height: 19px;
      color: #98a5a1;
    }

    .chevron svg {
      width: 100%;
      height: 100%;
      fill: none;
      stroke: currentColor;
      stroke-width: 2;
      stroke-linecap: round;
      stroke-linejoin: round;
    }

    .switch {
      position: relative;
      flex: 0 0 auto;
      width: 48px;
      height: 29px;
      display: inline-block;
    }

    .switch input {
      position: absolute;
      width: 1px;
      height: 1px;
      opacity: 0;
    }

    .slider {
      position: absolute;
      inset: 0;
      border-radius: 999px;
      background: var(--switch-off);
      cursor: pointer;
      transition: background 0.2s ease;
    }

    .slider::before {
      content: "";
      position: absolute;
      top: 3px;
      right: 3px;
      width: 23px;
      height: 23px;
      border-radius: 50%;
      background: #fff;
      box-shadow: 0 2px 6px rgba(0, 0, 0, 0.18);
      transition: transform 0.2s ease;
    }

    .switch input:checked + .slider {
      background: var(--primary);
    }

    .switch input:checked + .slider::before {
      transform: translateX(-19px);
    }

